// dev开发工具运行入口
import { toolEntry } from './entry.js'
// 扩展open页面
export function runDevTool() {
  console.log('=================== in runDevTool')

  toolEntry({
    click: (e) => {
      console.log('Button clicked!')
      const randomNum = Math.floor(Math.random() * 100000)
      sessionStorage.setItem('iidp_dev_tool_random', randomNum)

      window._iidp_dev_tool_current_starttime = new Date().getTime() // 记录当前点击新弹窗时间

      const newWindow = window.open(
        window.tech.routerBase + '?pageId=iidp_dev_open_page',
        '_blank',
        'width=1300,height=800,location=no'
      )

      // 窗口开启时隐藏开发按钮
      document.getElementById('tech-dev-btn').style.display = 'none'

      if (!newWindow) {
        // 失败时清除 sessionStorage
        sessionStorage.removeItem('iidp_dev_tool_random')
        return
      }

      newWindow.document.title = 'iidp前端调试'

      let cleaned = false // 🔥 防止重复清理

      const cleanup = () => {
        if (cleaned) return
        // 监听窗口关闭时显示开发按钮
        document.getElementById('tech-dev-btn').style.display = ''
        cleaned = true
        clearInterval(checkWindowClosed)
        window.removeEventListener('beforeunload', cleanup)
      }

      const checkWindowClosed = setInterval(() => {
        if (newWindow.closed) {
          cleanup() // 🔥 调用统一的清理函数
        }
      }, 1000)

      window.addEventListener('beforeunload', cleanup)
    }
  })
}

runDevTool()
