export function toolEntry(options = {}) {
  const mount = function () {
    if (!document || !document.body) return

    const id = 'tech-dev-btn'
    if (document.getElementById(id)) return

    const styleId = 'tech-dev-btn-style'
    if (!document.getElementById(styleId)) {
      const style = document.createElement('style')
      style.id = styleId
      style.type = 'text/css'
      style.textContent = `
        #${id} {
          position: fixed;
          top: 50%;
          right: 0;
          transform: translateY(-50%);
          width: 48px;
          height: 60px;
          display: flex;
          align-items: center;
          justify-content: center;
          padding: 0;
          color: #fff;
          background: rgba(33, 33, 33, 0.2);
          border-radius: 6px 0 0 6px;
          border: 1px solid rgba(255, 255, 255, 0.2);
          box-shadow: 0 8px 24px rgba(0, 0, 0, 0.2);
          font-weight: 600;
          letter-spacing: 1px;
          text-transform: uppercase;
          z-index: 2147483647;
          cursor: pointer;
          user-select: none;
          backdrop-filter: blur(2px);
          writing-mode: vertical-rl;
          text-orientation: mixed;
        }

        #${id}:hover { background: rgba(33, 33, 33, 0.7); }

        @media (max-width: 768px) {
          #${id} {
            width: 36px;
            height: 90px;
            font-size: 12px;
          }
        }
      `
      ;(document.head || document.getElementsByTagName('head')[0]).appendChild(style)
    }

    const btn = document.createElement('div')
    btn.id = id
    btn.innerText = '开发'
    btn.setAttribute('role', 'button')
    btn.setAttribute('aria-label', 'Developer Tools')

    // 拖动功能
    let dragging = false
    let clickTimer = null
    let position = { y: 0 }

    // 从localStorage加载位置
    const savedPosition = localStorage.getItem('tech-dev-btn-position')
    if (savedPosition) {
      try {
        const parsed = JSON.parse(savedPosition)
        if (typeof parsed.y === 'number') {
          position = parsed
          btn.style.top = `${parsed.y}px`
        }
      } catch (e) {
        // ignore
      }
    }

    btn.addEventListener('mousedown', function (e) {
      // 设置定时器，200ms后认为是拖拽
      clickTimer = setTimeout(() => {
        dragging = true
        position.y = e.clientY - btn.offsetTop
      }, 200)
      // 阻止默认的文本选择
      e.preventDefault()
    })

    document.addEventListener('mousemove', function (e) {
      if (dragging) {
        let newY = e.clientY - position.y

        const halfHeight = btn.offsetHeight / 2
        const maxY = window.innerHeight - halfHeight
        // const minY = -halfHeight

        if (newY < 0) {
          newY = 0
        }
        if (newY > maxY) {
          newY = maxY
        }
        btn.style.top = `${newY}px`
      } else if (clickTimer) {
        // 如果有轻微移动，也认为是拖拽，取消点击事件
        clearTimeout(clickTimer)
        clickTimer = null
        dragging = true
        position.y = e.clientY - btn.offsetTop
        btn.showPopup = false
      }
    })

    document.addEventListener('mouseup', function () {
      if (clickTimer) {
        // 如果在200ms内松开，认为是点击，显示弹窗
        clearTimeout(clickTimer)
        clickTimer = null
        btn.showPopup = true
      }
      if (dragging) {
        dragging = false
        // 保存位置到localStorage
        localStorage.setItem('tech-dev-btn-position', JSON.stringify({ y: btn.offsetTop }))
      }
    })

    btn.addEventListener('click', function (e) {
      if (!btn.showPopup) return
      e.preventDefault()
      e.stopPropagation()
      options?.click?.(e)
      // console.log('Button clicked!')
      // try {
      //   const ev = new CustomEvent('techDevButtonClick', { bubbles: true })
      //   btn.dispatchEvent(ev)
      // } catch (err) {
      //   // ignore
      // }
    })

    document.body.appendChild(btn)
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', mount, { once: true })
  } else {
    mount()
  }
}
